import pytest
from unittest.mock import patch, MagicMock
from alarm_clock import alarm
import winsound
from threading import *
from tkinter import *
import datetime
import time

# Test Class
class Test_AlarmClockAlarm:
    
    @pytest.mark.valid
    def test_alarm_trigger_at_correct_time(self):
        # Set alarm and current time to match
        set_time = "10:10:10"
        with patch("alarm_clock.hour.get", return_value="10"), \
             patch("alarm_clock.minute.get", return_value="10"), \
             patch("alarm_clock.second.get", return_value="10"), \
             patch("datetime.datetime.now") as mocked_datetime, \
             patch("winsound.PlaySound") as mocked_winsound:
          
            # Mock current time to match alarm time
            mocked_datetime.now.return_value = datetime.datetime.strptime(set_time, "%H:%M:%S")
            
            # Run alarm function with mocked time
            alarm()
            
            # Assert if sound is played
            mocked_winsound.assert_called_once_with("sound.wav", winsound.SND_ASYNC)

